ee:variables.ee:set-variable:
%dw 2.0
import modules::RiskRules
output application/java
var r = RiskRules::evaluate(vars.event, { velocityCount: vars.velocityCount, profile: null }, vars.riskCfg)
---
{ riskScore: r.score, riskBand: RiskRules::band(r.score, vars.riskCfg), ruleHits: r.hits, scoringFailed: false }
